    // Opt-in offline Player acceptance: only Records dependencies use fake writes.
    // Source/Transport and their actual command approval policies are not replaced.
    public sealed class RecordsQuickHudAcceptance : MonoBehaviour
    {
        string output;readonly List<string> log=new List<string>();
        BoardUartSource boards;ControlStudioDockLayout dock;ControlStudioRecordingPanel panel;
        ControlStudioBoardControlPanel control;RecordsQuickHud hud;ControlStudioOrbitCamera orbit;
        ControlStudioPresentationUI presentation;Rig right,left;bool fixtureVisible;
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        static void OptionalRun(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--records-quick-hud-verify");if(i<0||i+1>=args.Length)return;new GameObject("Explicit Quick HUD Fake UART acceptance").AddComponent<RecordsQuickHudAcceptance>().output=args[i+1];}
        void Check(bool ok,string text){log.Add((ok?"PASS: ":"FAIL: ")+text);if(!ok)throw new Exception(text);}
        void Save()=>File.WriteAllLines(Path.Combine(output,"quick_hud_result.txt"),log);
        bool SerialFree()=>boards.LogPath(BoardSide.Right).Length==0&&boards.LogPath(BoardSide.Left).Length==0&&boards.TxBytes(BoardSide.Right)==0&&boards.TxBytes(BoardSide.Left)==0;
        sealed class Rig:IDisposable
        {
            internal readonly BoardUartSession Session;internal readonly BoardCommandGateway Gateway;internal readonly BoardRecordingController Controller;internal readonly BoardRecordsUxFlow Flow;internal readonly List<string> Wires=new List<string>();readonly Func<bool> guard;
            internal readonly SortedDictionary<uint,string> Names=new SortedDictionary<uint,string>();
            internal Rig(BoardUartSession s,Func<bool> guard){this.guard=guard;Session=s;Session.Begin();Gateway=new BoardCommandGateway(s,guard,()=>true,()=>false,Enqueue,()=>BoardUartTransport.Now);Controller=new BoardRecordingController(Gateway);s.LineReceived+=Controller.ObserveLine;Flow=new BoardRecordsUxFlow(Controller,guard,()=>BoardUartTransport.Now,()=>new DateTime(2026,10,13,12,45,0));}
            bool Enqueue(long id,byte[] b,bool priority){if(!guard())return false;Wires.Add(Encoding.ASCII.GetString(b));Gateway.Sent(id,BoardUartTransport.Now);return true;}
            internal void Feed(string line){var b=Encoding.ASCII.GetBytes(line+"\r\n");Session.Feed(b,b.Length,BoardUartTransport.Now);Controller.Sync();Flow.Advance();}
            internal void State(string ui="IDLE",string mode="LIVE",bool pwm=true,bool unsaved=false,uint selected=0,uint playing=0)=>Feed("[REC_STATE] schema=1 side="+(Session.Side==BoardSide.Right?"r":"l")+" ui="+ui+" mode="+mode+" pwm="+(pwm?1:0)+" ram_samples=8 entries="+Names.Count+" selected="+selected+" playing="+playing+" delete=0 unsaved="+(unsaved?1:0));
            internal void Follow(bool on=true)=>Feed("[ST] async_test="+(on?1:0)+" pwm=1 result="+(on?Session.Side==BoardSide.Right?"enabled_UNSYNCHRONIZED_test":"enabled_remote_UNSYNCHRONIZED_test":Session.Side==BoardSide.Right?"disabled_new_async_targets":"disabled_new_remote_targets")+" mode=LIVE");
            internal void List(){string r=Session.Side==BoardSide.Right?"r":"l";Feed("[REC] SD records; select: "+r+" record select <number>");foreach(var e in Names)Feed("[REC] "+e.Key+" "+e.Value+" samples=8 duration_ms=160");Feed("[REC] count="+Names.Count+"; delete: "+r+" record delete <number>");}
            internal void Ready(){State();Follow(false);Feed("GM,0,0,0,0,0,0,0,0,0");Controller.RefreshList(out _);List();Wires.Clear();}
            public void Dispose(){Flow.Dispose();Session.LineReceived-=Controller.ObserveLine;Gateway.Dispose();}
        }
